from ortools.linear_solver import pywraplp

def solve_transportation(n, m, U, A, B, C):
    solver = pywraplp.Solver.CreateSolver('SCIP')
    # x[i][j]: amount of goods from warehouse i to supermarket j
    x = {}
    for i in range(n):
        for j in range(m):
            x[i, j] = solver.NumVar(0.0, min(A[i], B[j]), f'x_{i}_{j}')

    # Supermarket demand constraints
    for j in range(m):
        solver.Add(sum(x[i, j] for i in range(n)) >= B[j])

    # Warehouse capacity and minimum supply constraints
    for i in range(n):
        total_out = sum(x[i, j] for j in range(m))
        solver.Add(total_out <= A[i])
        solver.Add(total_out >= U)

    # Objective: minimize total cost
    solver.Minimize(sum(C[i][j] * x[i, j] for i in range(n) for j in range(m)))

    status = solver.Solve()
    if status == pywraplp.Solver.OPTIMAL:
        res = []
        for i in range(n):
            for j in range(m):
                val = x[i, j].solution_value()
                if val > 1e-6:
                    res.append((i + 1, j + 1, val))
        return len(res), res
    return None

from ortools.linear_solver import pywraplp

def solve_broadcasting(n, m, s, L, D, edges):
    # edges: list of (u, v, t, c)
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables: x[u, v] = 1 if edge (u, v) is selected in broadcasting tree
    x = {}
    for u, v, t, c in edges:
        x[u, v] = solver.IntVar(0, 1, f'x_{u}_{v}')

    # arr[v]: arrival time of package at node v from source s
    arr = {}
    for v in range(1, n + 1):
        arr[v] = solver.NumVar(0, L, f'arr_{v}')

    solver.Add(arr[s] == 0)

    # Tree structure: each node v != s has exactly one incoming edge
    for v in range(1, n + 1):
        if v != s:
            in_edges = [x[u, v] for u, v_target, t, c in edges if v_target == v]
            solver.Add(sum(in_edges) == 1)

    # Out-degree limit: each node u != s transmits to at most D nodes
    for u in range(1, n + 1):
        if u != s:
            out_edges = [x[u, v] for u_src, v, t, c in edges if u_src == u]
            solver.Add(sum(out_edges) <= D)

    # Time propagation constraint with Big-M
    M = 10000
    for u, v, t, c in edges:
        solver.Add(arr[v] >= arr[u] + t - M * (1 - x[u, v]))

    # Objective: minimize total cost
    solver.Minimize(sum(c * x[u, v] for u, v, t, c in edges))

    status = solver.Solve()
    if status == pywraplp.Solver.OPTIMAL:
        return int(solver.Objective().Value())
    return 'NO_SOLUTION'

from ortools.linear_solver import pywraplp

def solve_general_lp(n, m, dl, du, c, a, low, up):
    solver = pywraplp.Solver.CreateSolver('SCIP')

    x = []
    for i in range(n):
        x.append(solver.NumVar(dl[i], du[i], f'x_{i}'))

    for i in range(m):
        expr = sum(a[i][j] * x[j] for j in range(n))
        solver.Add(expr >= low[i])
        solver.Add(expr <= up[i])

    solver.Maximize(sum(c[i] * x[i] for i in range(n)))

    status = solver.Solve()
    if status == pywraplp.Solver.OPTIMAL:
        return [x[i].solution_value() for i in range(n)]
    else:
        return 'NOT_OPTIMAL'

from ortools.linear_solver import pywraplp

def solve_broadcast_tree(n, m, s, l, edges):
    model = pywraplp.Solver.CreateSolver('SCIP')
    x, arr = {}, {}

    for u, v, _, _ in edges:
        x[(u, v)] = model.IntVar(0, 1, f'x_{u}_{v}')

    for i in range(1, n + 1):
        arr[i] = model.NumVar(0, l, f'arr_{i}')

    model.Add(arr[s] == 0)

    # Each node except source has exactly 1 incoming link
    for v in range(1, n + 1):
        if v != s:
            model.Add(sum(x[(u, v)] for u, v_target, _, _ in edges if v_target == v) == 1)

    # Big-M constraint for transmission time
    M = 10000
    for u, v, t, c in edges:
        model.Add(arr[v] >= arr[u] + t - M * (1 - x[(u, v)]))

    # Objective: minimize cost
    model.Minimize(sum(c * x[(u, v)] for u, v, t, c in edges))

    status = model.Solve()
    if status == pywraplp.Solver.OPTIMAL:
        return int(model.Objective().Value())
    return None
